// Prueft, ob eine Umgebungsvariable im Code-Node ankommt, ohne den Wert auszugeben.
// process.env funktioniert in der Code-Node-Sandbox nicht, der Zugriff laeuft ueber $env.
// Je nach n8n-Version und Konfiguration ist $env zusaetzlich gesperrt (siehe README).
const name = 'DEMO_VARIABLE';
try {
  const laenge = String($env[name] ?? '').length;
  return [{ json: { name, ok: laenge > 0, laenge } }];
} catch (e) {
  return [{ json: { name, ok: false, hinweis: 'Zugriff auf $env blockiert oder Variable fehlt: ' + e.message } }];
}
